from datetime import datetime, timezone
raw = '''2026-11-24T08:00:05Z INFO iso line
1795507212 INFO epoch line
11/24/2026 08:00:20 INFO us line
03/04/2026 08:00:25 INFO ambiguous line'''
def norm(line):
    head, rest = line.split(" INFO ", 1)
    if "T" in head and head.endswith("Z"):
        return datetime.strptime(head, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc), "iso"
    if head.isdigit():
        return datetime.fromtimestamp(int(head), tz=timezone.utc), "epoch"
    try:
        us = datetime.strptime(head, "%m/%d/%Y %H:%M:%S")
        alt = datetime.strptime(head, "%d/%m/%Y %H:%M:%S")
        if us != alt:
            return None, "AMBIGUOUS"
    except ValueError:
        pass
    return datetime.strptime(head, "%m/%d/%Y %H:%M:%S").replace(tzinfo=timezone.utc), "us"
for line in raw.splitlines():
    dt, kind = norm(line)
    if dt is None:
        print("AMBIGUOUS: 03/04/2026 could be 2026-03-04 or 2026-04-03 - quarantined")
    else:
        print(f"{dt.strftime('%Y-%m-%dT%H:%M:%SZ')}  <- {kind}")

